pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 amount, uint256 ts) public {
        ts = bound(ts, 1, 2 ** 64);
        vm.warp(ts);
        address actor = address(0xABCD);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok == (amount == 10 ether), "success iff exactly 10 ether sent");
    }
}
